/**
 * A matemática das compras — a etiqueta que se reescreve enquanto o ajuste anda.
 *
 * O ponto do módulo é que porcentagem não é decoração da vitrine: é uma
 * multiplicação, e o mesmo slider que dá desconto (+) dá acréscimo (−). Por isso
 * a cena mostra as duas coisas na mesma régua — o preço cheio riscado, o preço
 * pago em destaque, e a barra em que a parte economizada e a parte paga a mais
 * crescem para lados opostos a partir do preço de tabela.
 *
 * A marca do alvo fica na régua o tempo todo: o investigador vê a distância que
 * falta, não só um "ajuste" no rodapé.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** `R$ 12,34` — a moeda do módulo é sempre o real. */
function reais(v: number): string {
  return `R$ ${v.toFixed(2).replace('.', ',')}`;
}

const desconto: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** A etiqueta pendurada: o retângulo com o furo e o cordão. */
  function etiquetaDePreco(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    largura: number,
    altura: number,
    tinta: string,
  ): void {
    const cor = paleta();
    const x = cx - largura / 2;
    const y = cy - altura / 2;

    ctx.save();
    ctx.fillStyle = 'rgb(35 42 85 / 10%)';
    ctx.beginPath();
    ctx.roundRect(x + 3, y + 4, largura, altura, altura * 0.16);
    ctx.fill();
    ctx.restore();

    retangulo(ctx, x, y, largura, altura, altura * 0.16, cor.contraste, tinta, 2.2);

    // O furo do cordão, no canto de cima à esquerda.
    const furo = altura * 0.09;
    ctx.fillStyle = cor.palha;
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.arc(x + furo * 2.4, y + furo * 2.4, furo, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.strokeStyle = MATERIAIS.corda;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x + furo * 2.4, y + furo * 2.4);
    ctx.lineTo(x + furo * 2.4 - altura * 0.16, y - altura * 0.16);
    ctx.stroke();
  }

  /** A régua do preço, de zero ao dobro da tabela. */
  function regua(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    preco: number,
    pago: number,
    alvo: number,
    tinta: string,
  ): void {
    const cor = paleta();
    const x0 = L * 0.08;
    const x1 = L * 0.92;
    const y = A * 0.775;
    const altura = limitar(A * 0.055, 9, 16);
    const teto = preco * 2;

    const px = (v: number): number => x0 + limitar(v / teto, 0, 1) * (x1 - x0);

    retangulo(ctx, x0, y, x1 - x0, altura, altura / 2, cor.palha, cor.trilho, 1);

    // A parte paga, sólida; da tabela até o pago, a diferença, hachurada.
    ctx.save();
    ctx.beginPath();
    ctx.roundRect(x0, y, x1 - x0, altura, altura / 2);
    ctx.clip();

    ctx.fillStyle = tinta;
    ctx.fillRect(x0, y, px(pago) - x0, altura);

    ctx.fillStyle = pago < preco ? 'rgb(47 143 92 / 30%)' : 'rgb(201 74 69 / 30%)';
    const de = Math.min(px(pago), px(preco));
    ctx.fillRect(de, y, Math.abs(px(preco) - px(pago)), altura);
    ctx.restore();

    // A tabela e o alvo, cada um com seu traço.
    const marca = (v: number, cor2: string, rotulo: string, acima: boolean): void => {
      ctx.strokeStyle = cor2;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(px(v), y - 5);
      ctx.lineTo(px(v), y + altura + 5);
      ctx.stroke();
      texto(
        ctx,
        rotulo,
        px(v),
        acima ? y - limitar(A * 0.032, 8, 11) : y + altura + limitar(A * 0.036, 9, 13),
        limitar(A * 0.03, 8, 11),
        { cor: cor2, peso: 700 },
      );
    };

    marca(preco, cor.fraco, `tabela ${reais(preco)}`, true);
    marca(alvo, cor.verde, `alvo ${reais(alvo)}`, false);
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const preco = numeroDe(info, 'preco', 35);
    const pago = numeroDe(info, 'pago', preco);
    const alvo = numeroDe(info, 'alvo', preco);
    const ajuste = Math.trunc(numeroDe(info, 'aj', 0));
    const fator = numeroDe(info, 'fator', 1);
    const diferenca = numeroDe(info, 'delta', 0);
    const ok = info.ok === true;

    // Sem ajuste a etiqueta continua azul, e não cinza: cinza lê como desligada,
    // e o preço cheio é uma resposta tão válida quanto as outras.
    const tinta = ok ? cor.verde : ajuste < 0 ? cor.erro : cor.azul;

    titulo(ctx, L, A, 'preço final = preço × (100 − ajuste) ÷ 100');

    // ── A etiqueta ───────────────────────────────────────────────────────
    const largura = Math.min(L * 0.62, A * 1.05);
    const altura = largura * 0.47;
    const cx = L / 2;
    const cy = A * 0.42;
    etiquetaDePreco(ctx, cx, cy, largura, altura, tinta);

    const grande = limitar(altura * 0.3, 14, 34);
    const medio = limitar(altura * 0.15, 9, 15);

    // O preço cheio, riscado quando houve ajuste.
    const yCheio = cy - altura * 0.16;
    texto(ctx, reais(preco), cx, yCheio, medio, { cor: cor.fraco, peso: 600 });
    if (ajuste !== 0) {
      const meia = ctx.measureText(reais(preco)).width / 2;
      ctx.strokeStyle = cor.erro;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(cx - meia - 3, yCheio);
      ctx.lineTo(cx + meia + 3, yCheio);
      ctx.stroke();
    }

    texto(ctx, reais(pago), cx, cy + altura * 0.1, grande, { cor: tinta, peso: 800 });
    texto(
      ctx,
      `${preco.toFixed(0)} × ${fator.toFixed(2).replace('.', ',')}`,
      cx,
      cy + altura * 0.32,
      medio,
      { cor: cor.fraco, peso: 600 },
    );

    // ── A tarja do ajuste, atravessada no canto ──────────────────────────
    if (ajuste !== 0) {
      const tarja = largura * 0.4;
      ctx.save();
      ctx.translate(cx + largura / 2 - tarja * 0.34, cy - altura / 2 + tarja * 0.2);
      ctx.rotate(-Math.PI / 9);
      retangulo(ctx, -tarja / 2, -medio, tarja, medio * 2, medio * 0.6, tinta);
      texto(ctx, `${ajuste > 0 ? '−' : '+'}${Math.abs(ajuste)}%`, 0, 0, medio * 1.15, {
        cor: cor.contraste,
        peso: 800,
      });
      ctx.restore();
    }

    regua(ctx, L, A, preco, pago, alvo, tinta);

    rodape(
      ctx,
      L,
      A,
      ok,
      `Fechou no alvo: ${reais(pago)} ✔`,
      ajuste === 0
        ? 'Sem ajuste nenhum: o preço é o de tabela.'
        : ajuste > 0
          ? `Economia de ${reais(diferenca)} — falta chegar ao alvo.`
          : `Você pagaria ${reais(-diferenca)} a mais.`,
      ajuste < 0 ? cor.erro : cor.fraco,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default desconto;
